/* Signature Slovenian Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Janezmir": "From Janez + mir (peace).", "Marijaslava": "From Marija + slava (glory).", "Francmil": "From Franc + mil (dear).", "Anagora": "From Ana + gora (mountain).", "Markomorje": "From Marko + morje (sea).", "Evasanje": "From Eva + sanje (dreams).", "Janezmirovic": "Signature surname in -ic style.", "Marijaslavnik": "Signature surname in -nik style.", "Francmilic": "Signature surname in -ic style.", "Anagoric": "Signature surname in -ic style."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Janezmir';
console.log(lookup(q));

